<?php
require_once dirname(__DIR__).'/includes/bootstrap.php';require_role('administrador');$pageTitle='Contenido';$errors=[];$current=null;if(isset($_GET['t'])){$id=decode_id($_GET['t']);if(!$id)abort_forbidden('Token alterado.');$s=db()->prepare('SELECT * FROM contenido_sitio WHERE id=?');$s->execute([$id]);$current=$s->fetch();}
if(request_is_post()){verify_csrf();$fa=clean_text($_POST['form_action']??'',20);if(in_array($fa,['create','update'],true)){$key=slugify(clean_text($_POST['clave']??'',120));$title=clean_text($_POST['titulo']??'',180);$content=clean_multiline($_POST['contenido']??'',10000);$active=isset($_POST['activo'])?1:0;if($key==='')$errors[]='Escribe una clave.';if(mb_strlen($content)<3)$errors[]='Escribe el contenido.';$id=$fa==='update'?decode_id($_POST['token_id']??''):null;if($fa==='update'&&!$id)abort_forbidden('Token alterado.');$check=db()->prepare('SELECT id FROM contenido_sitio WHERE clave=?'.($id?' AND id<>?':''));$check->execute($id?[$key,$id]:[$key]);if($check->fetch())$errors[]='La clave ya existe.';if(!$errors){if($fa==='create')db()->prepare('INSERT INTO contenido_sitio(clave,titulo,contenido,activo)VALUES(?,?,?,?)')->execute([$key,$title?:null,$content,$active]);else db()->prepare('UPDATE contenido_sitio SET clave=?,titulo=?,contenido=?,activo=?,updated_at=NOW() WHERE id=?')->execute([$key,$title?:null,$content,$active,$id]);flash('success','Contenido guardado.');redirect('admin/contenido.php');}}if($fa==='delete'){$id=decode_id($_POST['token_id']??'');if(!$id)abort_forbidden('Token alterado.');db()->prepare('DELETE FROM contenido_sitio WHERE id=?')->execute([$id]);flash('success','Contenido eliminado.');redirect('admin/contenido.php');}}
$items=db()->query('SELECT * FROM contenido_sitio ORDER BY clave')->fetchAll();require dirname(__DIR__).'/includes/admin_header.php';
?>
<div class="panel-heading"><div><h1>Contenido del sitio</h1><p>Textos administrables para secciones corporativas.</p></div></div><div class="grid-2"><form class="card" method="post"><?=csrf_field()?><input type="hidden" name="form_action" value="<?=$current?'update':'create'?>"><?php if($current):?><input type="hidden" name="token_id" value="<?=e(encode_id((int)$current['id']))?>"><?php endif;?><h2><?=$current?'Editar contenido':'Nuevo contenido'?></h2><?php if($errors):?><div class="error-list"><ul><?php foreach($errors as$er):?><li><?=e($er)?></li><?php endforeach;?></ul></div><?php endif;?><div class="field"><label>Clave única</label><input name="clave" value="<?=e($current['clave']??'')?>" placeholder="empresa-mision" required></div><div class="field"><label>Título</label><input name="titulo" value="<?=e($current['titulo']??'')?>"></div><div class="field"><label>Contenido</label><textarea name="contenido" required><?=e($current['contenido']??'')?></textarea></div><label><input type="checkbox" name="activo" style="width:auto" <?=!$current||$current['activo']?'checked':''?>> Activo</label><div class="actions"><button class="btn">Guardar</button><?php if($current):?><a class="btn btn-light" href="<?=url('admin/contenido.php')?>">Cancelar</a><?php endif;?></div></form><div class="table-card"><div class="table-responsive"><table><thead><tr><th>Clave</th><th>Título</th><th>Estado</th><th></th></tr></thead><tbody><?php foreach($items as$it):?><tr><td><?=e($it['clave'])?></td><td><?=e($it['titulo']??'—')?></td><td><?=$it['activo']?'Activo':'Inactivo'?></td><td class="table-actions"><a class="btn btn-small btn-light" href="<?=url('admin/contenido.php?t='.encode_id((int)$it['id']))?>">Editar</a><form method="post"><?=csrf_field()?><input type="hidden" name="form_action" value="delete"><input type="hidden" name="token_id" value="<?=e(encode_id((int)$it['id']))?>"><button class="btn btn-small btn-danger" data-confirm="¿Eliminar este contenido?">Eliminar</button></form></td></tr><?php endforeach;?></tbody></table></div></div></div>
<?php require dirname(__DIR__).'/includes/admin_footer.php';?>
